//! The files around a bike's geometry: the mod's `mod.toml` and the car's manifest `cars/<id>.toml`.

use std::path::Path;

use anyhow::{Context, Result};

use crate::build::Built;
use crate::layout;

/// The `mod.toml` of the content mod: no library, only `cars/` and `files/`.
pub const MOD_TOML: &str = r#"# Bikes of the user's own RIDE 6 install, converted by `ride6-bike-import` (mods/ride6-bikes/README.md).
# A content-only mod: it holds `cars/` and `files/` and no library. The generated files belong to the user's install
# of RIDE 6 and are never committed.

[mod]
id = "ride6-bikes"
name = "RIDE 6 bikes"
version = "0.1.0"
authors = ["nfs-mw contributors"]
license = "MIT OR Apache-2.0"

[api]
blackbox_modding = "0.1"

[games]
supported = ["nfsmw"]
"#;

/// The manifest of the KTM 450 SMR 2022. The numbers come from the bike's own physics data (`KTM_450SMR_2022`: mass
/// 113 kg, rake 26.1 degrees) where the car stats can hold them and are placeholders elsewhere: the engine builds a
/// four-wheel car, so the bike drives as a very narrow one (the table's smallest mass is 200 kg and smallest track
/// 0.8 m).
pub fn car_toml(built: &Built) -> String {
    let radius = built.tyre_radius;
    format!(
        r#"# The KTM 450 SMR 2022 of RIDE 6 as a car of NFS: Most Wanted. Generated by `ride6-bike-import`.
role = "player"
name = "KTM 450 SMR"
manufacturer = "KTM"

[stats]
mass_kg = 200.0
cg_height_m = 0.67
wheelbase_m = {wheelbase:.4}
front_track_m = 0.8
rear_track_m = 0.8
front_tire_radius_m = {radius:.3}
rear_tire_radius_m = {radius:.3}
front_tire_width_m = 0.12
rear_tire_width_m = 0.15
idle_rpm = 1800.0
redline_rpm = 11000.0
torque_curve = [[1800.0, 30.0], [4000.0, 38.0], [7500.0, 47.0], [9500.0, 45.0], [11000.0, 36.0]]
gear_ratios = [2.9, 2.1, 1.7, 1.4, 1.2, 1.05]
final_drive = 3.0
top_speed_kph = 160.0
front_tire_grip = 1.3
rear_tire_grip = 1.3
"#,
        wheelbase = layout::wheelbase(),
    )
}

/// Write the mod's files into `mod_dir`: `mod.toml`, `cars/<id>.toml` and `files/CARS/<ID>/`.
pub fn write(mod_dir: &Path, folder: &str, built: &Built) -> Result<()> {
    let id = folder.to_ascii_uppercase();
    let car_dir = mod_dir.join("files").join("CARS").join(&id);
    std::fs::create_dir_all(&car_dir).with_context(|| format!("creating {}", car_dir.display()))?;
    std::fs::create_dir_all(mod_dir.join("cars"))?;
    for (name, bytes) in
        [("GEOMETRY.BIN", &built.geometry), ("TEXTURES.BIN", &built.textures), ("BOUNDS.BIN", &built.bounds)]
    {
        std::fs::write(car_dir.join(name), bytes).with_context(|| format!("writing {name}"))?;
    }
    std::fs::write(mod_dir.join("cars").join(format!("{}.toml", id.to_ascii_lowercase())), car_toml(built))?;
    std::fs::write(mod_dir.join("mod.toml"), MOD_TOML)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_manifest_is_valid_toml_with_the_stats_table() {
        let built = Built {
            geometry: vec![],
            textures: vec![],
            bounds: vec![],
            half: [0.4, 0.6, 1.0],
            tyre_radius: 0.32,
            triangles: 0,
        };
        let text = car_toml(&built);
        assert!(text.contains("wheelbase_m = 1.4745"));
        assert!(text.contains("front_tire_radius_m = 0.320"));
        assert!(text.contains("[stats]"));
    }
}
